package com.bank.product.service;

import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

// Generates every possible service bundle (subset) via iterative doubling.
public class SubsetsService {
    private static final Logger log = Logger.getLogger(SubsetsService.class.getName());

    public List<List<String>> allBundles(List<String> services) {
        List<List<String>> bundles = new ArrayList<>();
        bundles.add(new ArrayList<>()); // the empty bundle
        for (String service : services) {
            int size = bundles.size(); // snapshot BEFORE adding this round
            for (int i = 0; i < size; i++) {
                List<String> copy = new ArrayList<>(bundles.get(i));
                copy.add(service);
                bundles.add(copy);
            }
            log.fine(() -> "After adding " + service + " total bundles = " + bundles.size());
        }
        log.info(() -> "Generated " + bundles.size() + " bundles");
        return bundles;
    }
}
